require_once __DIR__ . '/../config/db.php';
?>
<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Clientes / Delivery</title>
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"></head>
<body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="index.php"><i class="bi bi-arrow-left me-2"></i>Caixa</a><span class="navbar-text text-white">Clientes / Delivery</span></div></nav>
<main class="container py-4"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h1 class="h3 mb-1">Clientes / Delivery</h1><p class="text-muted mb-0">Gerencie contatos e endereços de entrega.</p></div><button class="btn btn-primary" id="novoCliente"><i class="bi bi-person-plus me-1"></i>Novo cliente</button></div>
<div class="card"><div class="card-body"><input class="form-control mb-3" id="pesquisaClientes" placeholder="Buscar por nome ou telefone"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Cliente</th><th>Telefone</th><th>Endereço</th><th class="text-end">Ações</th></tr></thead><tbody id="linhasClientes"><tr><td colspan="4" class="text-center text-muted">Carregando...</td></tr></tbody></table></div><nav><ul class="pagination justify-content-center mb-0" id="paginacao"></ul></nav></div></div></main>
<div class="modal fade" id="modalEditarCliente" tabindex="-1"><div class="modal-dialog modal-lg"><form class="modal-content" id="formEditarCliente"><div class="modal-header"><h2 class="modal-title fs-5">Cadastro de cliente</h2><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="id"><div class="row g-3">
<?php $fields=[['nome','Nome completo',true],['telefone','Telefone / WhatsApp',true],['cep','CEP',false],['logradouro','Logradouro',true],['numero','Número',true],['complemento','Complemento',false],['bairro','Bairro',true],['cidade','Cidade',false],['ponto_referencia','Ponto de referência',false],['observacoes','Observações',false]]; foreach($fields as [$name,$label,$required]): ?><div class="col-md-<?= in_array($name,['logradouro','observacoes'])?8:4 ?>"><label class="form-label" for="edit_<?= $name ?>"><?= $label ?></label><?php if($name==='cep'): ?><div class="input-group"><input class="form-control" id="edit_cep" name="cep" maxlength="9" inputmode="numeric" autocomplete="postal-code"><span class="input-group-text d-none" id="edit_cep_spinner"><span class="spinner-border spinner-border-sm" role="status" aria-label="Consultando CEP"></span></span></div><div class="small text-danger d-none" id="edit_cep_feedback"></div><?php else: ?><input class="form-control" id="edit_<?= $name ?>" name="<?= $name ?>" <?= $required?'required':'' ?>><?php endif; ?></div><?php endforeach; ?></div><div class="alert alert-danger d-none mt-3" id="erroCliente"></div></div><div class="modal-footer"><button class="btn btn-secondary" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Salvar cliente</button></div></form></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>
const modalCliente=new bootstrap.Modal(document.getElementById('modalEditarCliente')), corpoClientes=document.getElementById('linhasClientes');let paginaClientes=1, buscaClientes='',clientesCache={};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function listarClientes(p=1){paginaClientes=p;const q=new URLSearchParams({pagina:p,limite:10});if(buscaClientes)q.set('busca',buscaClientes);const r=await fetch('api_clientes.php?'+q),d=await r.json();clientesCache=Object.fromEntries(d.clientes.map(c=>[c.id,c]));corpoClientes.innerHTML=d.clientes.length?d.clientes.map(c=>`<tr><td class="fw-semibold">${esc(c.nome)}</td><td>${esc(c.telefone)}</td><td>${esc([c.logradouro,c.numero,c.complemento,c.bairro,c.cidade].filter(Boolean).join(', '))}</td><td class="text-end text-nowrap"><button class="btn btn-sm btn-outline-primary me-1" onclick="editarCliente(${c.id})"><i class="bi bi-pencil"></i> Editar</button><button class="btn btn-sm btn-outline-danger" onclick="excluirCliente(${c.id})"><i class="bi bi-trash"></i></button></td></tr>`).join(''):'<tr><td colspan="4" class="text-center text-muted">Nenhum cliente encontrado.</td></tr>';document.getElementById('paginacao').innerHTML=Array.from({length:d.paginas},(_,i)=>`<li class="page-item ${i+1===d.pagina?'active':''}"><button class="page-link" onclick="listarClientes(${i+1})">${i+1}</button></li>`).join('')}
function editarCliente(id=null){const c=id?clientesCache[id]:null,f=document.getElementById('formEditarCliente');f.reset();f.elements.id.value=c?.id||'';['nome','telefone','cep','logradouro','numero','complemento','bairro','cidade','ponto_referencia','observacoes'].forEach(k=>f.elements[k].value=c?.[k]||'');f.dataset.cepConsultado='';document.getElementById('edit_cep_feedback').classList.add('d-none');modalCliente.show()}
const cepEdicao=document.getElementById('edit_cep');
function mascaraCep(valor){const digitos=valor.replace(/\D/g,'').slice(0,8);return digitos.length>5?`${digitos.slice(0,5)}-${digitos.slice(5)}`:digitos}
async function consultarCepEdicao(){const cep=cepEdicao.value.replace(/\D/g,'');if(cep.length!==8||document.getElementById('formEditarCliente').dataset.cepConsultado===cep)return;document.getElementById('formEditarCliente').dataset.cepConsultado=cep;const f=document.getElementById('formEditarCliente'),feedback=document.getElementById('edit_cep_feedback'),spinner=document.getElementById('edit_cep_spinner'),campos=['logradouro','numero','complemento','bairro','cidade','ponto_referencia'].map(n=>f.elements[n]);feedback.classList.add('d-none');campos.forEach(c=>c.disabled=true);spinner.classList.remove('d-none');try{const r=await fetch(`https://viacep.com.br/ws/${cep}/json/`),data=await r.json();if(cepEdicao.value.replace(/\D/g,'')!==cep)return;if(data.erro){['logradouro','bairro','cidade'].forEach(n=>f.elements[n].value='');feedback.textContent='CEP não encontrado. Preencha o endereço manualmente.';feedback.classList.remove('d-none');return}f.elements.logradouro.value=data.logradouro||'';f.elements.bairro.value=data.bairro||'';f.elements.cidade.value=data.localidade||'';f.elements.numero.focus()}catch(_){feedback.textContent='Não foi possível consultar o CEP. Preencha o endereço manualmente.';feedback.classList.remove('d-none')}finally{campos.forEach(c=>c.disabled=false);spinner.classList.add('d-none')}}
cepEdicao.addEventListener('input',()=>{cepEdicao.value=mascaraCep(cepEdicao.value);document.getElementById('edit_cep_feedback').classList.add('d-none');if(cepEdicao.value.replace(/\D/g,'').length===8)consultarCepEdicao()});cepEdicao.addEventListener('blur',consultarCepEdicao);
document.getElementById('novoCliente').onclick=()=>editarCliente();let timerBusca;document.getElementById('pesquisaClientes').oninput=e=>{clearTimeout(timerBusca);timerBusca=setTimeout(()=>{buscaClientes=e.target.value;listarClientes(1)},250)};
document.getElementById('formEditarCliente').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f));try{let r=await fetch('api_clientes.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),j=await r.json();if(j.duplicado&&confirm('Este telefone pertence a outro cadastro. Atualizar esse cliente com os dados informados?')){d.confirmar_atualizacao=true;r=await fetch('api_clientes.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});j=await r.json()}if(!j.sucesso)throw Error(j.erro);modalCliente.hide();listarClientes(paginaClientes)}catch(err){const box=document.getElementById('erroCliente');box.textContent=err.message;box.classList.remove('d-none')}};
async function excluirCliente(id){if(!confirm(`Excluir o cadastro de ${clientesCache[id]?.nome||'cliente'}?`))return;const r=await fetch('api_clientes.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:'excluir',id})}),d=await r.json();if(!d.sucesso)alert(d.erro);else listarClientes(paginaClientes)}listarClientes();
</script></body></html>
